import{_ as a,o as t,c as o,ag as n}from"./chunks/framework.XeSgnAkN.js";const h=JSON.parse('{"title":"Privacy","description":"","frontmatter":{},"headers":[],"relativePath":"privacy.md","filePath":"privacy.md","lastUpdated":1791226614000}'),i={name:"privacy.md"};function s(r,e,c,l,d,u){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="privacy" tabindex="-1">Privacy <a class="header-anchor" href="#privacy" aria-label="Permalink to &quot;Privacy&quot;">​</a></h1><p>Pigeon is local-first.</p><h2 id="stored-data" tabindex="-1">Stored data <a class="header-anchor" href="#stored-data" aria-label="Permalink to &quot;Stored data&quot;">​</a></h2><ul><li>tasks in local markdown files</li><li>app preferences in UserDefaults</li></ul><h2 id="pigeon-cloud-optional" tabindex="-1">Pigeon Cloud (optional) <a class="header-anchor" href="#pigeon-cloud-optional" aria-label="Permalink to &quot;Pigeon Cloud (optional)&quot;">​</a></h2><p>Pigeon Cloud is off until you connect it in Settings. When it is connected:</p><ul><li><strong>What is stored:</strong> your email address, and a copy of your task files and notes. This data lets AI agents you connect (such as Claude) and your other devices use your inbox.</li><li><strong>Where:</strong> on Cloudflare, in a storage unit dedicated to your account. Sign-in codes are sent by email through Resend.</li><li><strong>Who can access it:</strong> only apps and agents you approve on the sign-in page. You can see and disconnect them at any time in Settings → Pigeon Cloud → Connected apps.</li><li><strong>Deleting your data:</strong> Settings → Pigeon Cloud → Delete account… disconnects every app and agent, then permanently deletes the cloud copy of your tasks and notes and your account. Files in your local folder are not touched.</li><li><strong>Disconnecting a Mac:</strong> this stops syncing and revokes that Mac&#39;s access. Cloud data stays until you delete the account.</li></ul><h2 id="crash-diagnostics" tabindex="-1">Crash diagnostics <a class="header-anchor" href="#crash-diagnostics" aria-label="Permalink to &quot;Crash diagnostics&quot;">​</a></h2><p>Disabled by default.</p><p>When enabled, diagnostics include technical metadata only (version, OS, operation context). Task text content is excluded.</p><h2 id="app-store-disclosure-summary" tabindex="-1">App Store disclosure summary <a class="header-anchor" href="#app-store-disclosure-summary" aria-label="Permalink to &quot;App Store disclosure summary&quot;">​</a></h2><ul><li>Pigeon does not track users across apps or websites.</li><li>Pigeon does not collect task content for analytics or advertising.</li><li>With Pigeon Cloud connected, your email address and task content are stored to provide sync and agent access. They are linked to your account, never used for tracking, and deleted with the account.</li><li>Crash diagnostics are optional and controlled by the user.</li><li>Privacy manifest is provided via <code>quickbox/PrivacyInfo.xcprivacy</code>.</li></ul>',12)])])}const g=a(i,[["render",s]]);export{h as __pageData,g as default};
